INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_pathao', '{"sections":[{"id":"products","title":{"en":"Products & services","bn":"প্রোডাক্ট ও সেবা"},"body":{"en":"Pathao connects consumers with rides, food delivery and parcel services through its app. Its courier business serves merchants shipping orders to customers. These serve different needs: a consumer booking a trip or meal, and a business managing repeat deliveries.","bn":"Pathao অ্যাপ দিয়ে রাইড নেওয়া, খাবার অর্ডার করা ও পার্সেল পাঠানো যায়। ব্যবসায়ীরা ক্রেতার কাছে অর্ডার পৌঁছে দিতে তাদের কুরিয়ার সেবা ব্যবহার করেন। একদিকে ব্যক্তিগত যাতায়াত বা খাবারের প্রয়োজন মেটে, অন্যদিকে ব্যবসার নিয়মিত ডেলিভারি সামলানো যায়।"},"sources":[{"title":"Pathao - services and company overview","url":"https://pathao.com/about-us/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]},{"id":"merchant-services","title":{"en":"Tools for merchants","bn":"ব্যবসায়ীদের জন্য সেবা"},"body":{"en":"Pathao Courier offers parcel tracking, cash-on-delivery collection, returns and fulfilment support such as inventory management, packing and order processing. Merchants register through a separate portal. Its courier support number is 09610003030; confirm service areas, payout terms and return charges before choosing a delivery setup.","bn":"পার্সেল কোথায় আছে তা দেখা, ডেলিভারির সময় টাকা সংগ্রহ ও ফেরত আসা পণ্য সামলানোর সুবিধা দেয় Pathao Courier। স্টক রাখা, প্যাকিং ও অর্ডার প্রক্রিয়া করার সেবাও আছে। ব্যবসায়ীদের আলাদা পোর্টালে নিবন্ধন করতে হয়। কুরিয়ারের সহায়তা নম্বর ০৯৬১০০০৩০৩০। কাজ শুরুর আগে ডেলিভারির এলাকা, টাকা পাওয়ার নিয়ম ও রিটার্নের খরচ মিলিয়ে নিন।"},"sources":[{"title":"Pathao Courier - merchant services","url":"https://pathao.com/courier/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[{"label":{"en":"Courier services","bn":"কুরিয়ার সেবা"},"url":"https://pathao.com/courier/"},{"label":{"en":"Merchant registration","bn":"ব্যবসায়ী হিসেবে নিবন্ধন"},"url":"https://merchant.pathao.com/register"}]},{"id":"commerce","title":{"en":"Pathao Commerce","bn":"Pathao Commerce"},"body":{"en":"In September 2026, Pathao announced Commerce, a platform for managing storefronts, sales channels, orders, inventory, payments, delivery and customer communication together. It extends the merchant offering beyond moving parcels to coordinating the work around an order.","bn":"২০২৬ সালের সেপ্টেম্বরে Pathao Commerce চালুর ঘোষণা দেয় কোম্পানিটি। অনলাইন দোকান, বিক্রির চ্যানেল, অর্ডার, স্টক, পেমেন্ট, ডেলিভারি ও ক্রেতার সঙ্গে যোগাযোগ এক জায়গায় সামলানোর জন্য এই প্ল্যাটফর্ম। পার্সেল পৌঁছে দেওয়ার পাশাপাশি অর্ডার ঘিরে ব্যবসায়ীর বাকি কাজগুলোও এতে রাখা যায়।"},"sources":[{"title":"Pathao Commerce launch","url":"https://pathao.com/blog/press/pathao-commerce/","publishedOn":"2026-09-10","checkedAt":"2026-09-21"}],"links":[{"label":{"en":"Commerce announcement","bn":"Commerce চালুর ঘোষণা"},"url":"https://pathao.com/blog/press/pathao-commerce/"}]}],"contact":{"address":{"en":"Jahanara Garden, House 103, Road 13/A, Block C, Banani, Dhaka.","bn":"জাহানারা গার্ডেন, বাড়ি ১০৩, রোড ১৩/এ, ব্লক সি, বনানী, ঢাকা।"},"email":null,"phone":"09678100800","sources":[{"title":"Pathao - official contact information","url":"https://pathao.com/contact/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('profile-batch1-pathao', 'org_pathao', 'review', 'editorial:company-profile-batch-1', '2026-09-21', '{"scope":"Official products, services and contact information; previous editorial claims retain their dates."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_dorik', '{"sections":[{"id":"products","title":{"en":"Website building tools","bn":"ওয়েবসাইট তৈরির টুল"},"body":{"en":"Dorik combines AI-assisted website generation with a visual editor, templates and reusable page elements. It includes hosting, custom-domain support, forms and blogging tools. Founders can use it to build and maintain a marketing site without writing every page in code.","bn":"এআই দিয়ে ওয়েবসাইটের খসড়া তৈরি করে Dorik-এর ভিজুয়াল এডিটরে তা সাজানো যায়। টেমপ্লেট ও আগে থেকে তৈরি পেজের অংশও আছে। হোস্টিং, নিজের ডোমেইন যুক্ত করা, ফর্ম ও ব্লগের সুবিধা দেয় Dorik। ফাউন্ডাররা প্রতিটি পেজের কোড না লিখেও ব্যবসার ওয়েবসাইট তৈরি ও আপডেট করতে পারেন।"},"sources":[{"title":"Dorik - website building features","url":"https://dorik.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[{"label":{"en":"Website builder","bn":"ওয়েবসাইট বিল্ডার"},"url":"https://dorik.com/"},{"label":{"en":"Plans & limits","bn":"প্ল্যান ও সীমা"},"url":"https://dorik.com/pricing"}]},{"id":"agency-tools","title":{"en":"CMS & agency workflow","bn":"CMS ও এজেন্সির কাজ"},"body":{"en":"The white-label CMS lets agencies use their own branding and give clients a dedicated dashboard. It supports structured content and a public API, alongside client billing tools. This makes client-site management a distinct part of Dorik’s offering, beyond individual website creation.","bn":"এজেন্সিগুলো Dorik-এর হোয়াইট-লেবেল CMS-এ নিজেদের ব্র্যান্ড ব্যবহার করতে পারে। ক্লায়েন্টকে আলাদা ড্যাশবোর্ড দেওয়া, নির্দিষ্ট কাঠামোয় কনটেন্ট রাখা, পাবলিক API ব্যবহার ও বিল পাঠানোর সুবিধাও আছে। ফলে শুধু একটি ওয়েবসাইট বানানো নয়, ক্লায়েন্টদের সাইট সামলানোর কাজেও Dorik ব্যবহার করা যায়।"},"sources":[{"title":"Dorik - white-label CMS","url":"https://dorik.com/white-label-cms","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[{"label":{"en":"White-label CMS","bn":"হোয়াইট-লেবেল CMS"},"url":"https://dorik.com/white-label-cms"}]},{"id":"origins","title":{"en":"How it started","bn":"শুরুর গল্প"},"body":{"en":"Dorik’s own history traces the product to a 2019 side project, followed by an April 2020 landing page to recruit early users. It records its first paying customer in July and public launch in August 2020. The helpdesk and live chat are the main published support routes.","bn":"Dorik-এর নিজের বর্ণনা অনুযায়ী, ২০১৯ সালে অন্য কাজের পাশাপাশি প্রোডাক্টটি বানানো শুরু হয়। প্রথম ব্যবহারকারীদের খুঁজতে ২০২০ সালের এপ্রিলে একটি ল্যান্ডিং পেজ প্রকাশ করে তারা। জুলাইয়ে প্রথম ক্রেতা টাকা দেন, আর আগস্টে সবার জন্য প্রোডাক্টটি চালু হয়। সহায়তার জন্য হেল্পডেস্ক ও লাইভ চ্যাট আছে।"},"sources":[{"title":"Dorik - company story","url":"https://dorik.com/about-dorik","publishedOn":null,"checkedAt":"2026-09-21"},{"title":"Dorik - website building features","url":"https://dorik.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[{"label":{"en":"Helpdesk","bn":"হেল্পডেস্ক"},"url":"https://help.dorik.com/en/"}]}],"contact":{"address":null,"email":"support@dorik.com","phone":null,"sources":[{"title":"Dorik - published support email","url":"https://help.dorik.com/en/article/terms-of-service-1ct7bc/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('profile-batch1-dorik', 'org_dorik', 'review', 'editorial:company-profile-batch-1', '2026-09-21', '{"scope":"Official products, services and contact information; previous editorial claims retain their dates."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_ifarmer', '{"sections":[{"id":"services","title":{"en":"Finance, inputs & market access","bn":"অর্থায়ন, কৃষি উপকরণ ও বাজার"},"body":{"en":"iFarmer connects farmers, agricultural retailers and institutional buyers. Its services combine access to finance, seeds and other inputs, agricultural advice and routes to sell produce. For financial institutions, it provides farmer profiles, credit information and supply-chain data to support financing decisions.","bn":"কৃষক, কৃষি উপকরণের দোকান ও প্রাতিষ্ঠানিক ক্রেতাদের যুক্ত করে iFarmer। অর্থায়ন পাওয়ার সুযোগ, বীজসহ কৃষি উপকরণ, চাষের পরামর্শ ও উৎপাদিত পণ্য বিক্রির ব্যবস্থা নিয়ে কাজ করে তারা। অর্থায়নের সিদ্ধান্ত নিতে আর্থিক প্রতিষ্ঠানগুলোকে কৃষকের প্রোফাইল, ঋণসংক্রান্ত তথ্য ও সরবরাহব্যবস্থার ডেটা দেয়।"},"sources":[{"title":"iFarmer - services and Bangladesh office","url":"https://www.ifarmer.asia/about","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]},{"id":"folon","title":{"en":"Folon for farmers","bn":"কৃষকদের জন্য Folon"},"body":{"en":"Folon gives farmers crop advice in text and audio, a way to send pictures or voice messages to agricultural experts, and a community called Adda. The app also provides a route to apply for loans.","bn":"Folon-এ কৃষকেরা ফসলের পরামর্শ পড়তে বা শুনতে পারেন। ছবি ও ভয়েস মেসেজ পাঠিয়ে কৃষিবিশেষজ্ঞদের সঙ্গে কথাও বলা যায়। অন্য কৃষকদের সঙ্গে আলাপের জন্য আছে Adda কমিউনিটি। অ্যাপ থেকে ঋণের আবেদন করার সুযোগও আছে।"},"sources":[{"title":"iFarmer - Folon farmer application","url":"https://www.ifarmer.asia/product-folon","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[{"label":{"en":"Explore Folon","bn":"Folon সম্পর্কে জানুন"},"url":"https://www.ifarmer.asia/product-folon"}]},{"id":"krishop","title":{"en":"KriShop for agricultural inputs","bn":"কৃষি উপকরণের জন্য KriShop"},"body":{"en":"KriShop lets agricultural input retailers order supplies through an e-commerce platform. Its Lenden digital logbook records daily transactions online or offline and can send SMS reminders for unpaid balances. A retailer community adds a place to exchange advice and discuss business problems.","bn":"কৃষি উপকরণের দোকানগুলো KriShop-এর ই-কমার্স প্ল্যাটফর্ম থেকে পণ্য অর্ডার করতে পারে। এর Lenden ডিজিটাল খাতায় অনলাইন বা অফলাইনে দৈনিক লেনদেন লিখে রাখা যায়। বকেয়া টাকার কথা মনে করিয়ে দিতে ক্রেতাকে এসএমএসও পাঠানো যায়। অন্য দোকানিদের সঙ্গে পরামর্শ ও ব্যবসার সমস্যা নিয়ে আলাপের জন্য একটি কমিউনিটি আছে।"},"sources":[{"title":"iFarmer - KriShop input platform","url":"https://www.ifarmer.asia/product-krishop","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[{"label":{"en":"Explore KriShop","bn":"KriShop সম্পর্কে জানুন"},"url":"https://www.ifarmer.asia/product-krishop"}]}],"contact":{"address":{"en":"Bangladesh office: House NE (B) 3B, Road 74, Gulshan 2, Dhaka 1212. Visits by appointment.","bn":"বাংলাদেশের অফিস: বাড়ি এনই (বি) ৩বি, রোড ৭৪, গুলশান ২, ঢাকা ১২১২। যাওয়ার আগে সময় ঠিক করে নিতে হয়।"},"email":"hello@ifarmer.asia","phone":"+8808008500800","sources":[{"title":"iFarmer - services and Bangladesh office","url":"https://www.ifarmer.asia/about","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('profile-batch1-ifarmer', 'org_ifarmer', 'review', 'editorial:company-profile-batch-1', '2026-09-21', '{"scope":"Official products, services and contact information; previous editorial claims retain their dates."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_startup-bangladesh-limited', '{"sections":[{"id":"mandate","title":{"en":"Who backs the organization","bn":"প্রতিষ্ঠানটির পেছনে কারা আছে"},"body":{"en":"Startup Bangladesh is the government-sponsored venture capital organization under the ICT Division. It describes a mandate covering direct startup investment, co-investment and fund-of-funds activity, alongside non-financial support. These are different routes: a startup seeking investment and a fund manager seeking backing use different application processes.","bn":"আইসিটি বিভাগের অধীনে সরকারি অর্থায়নে গড়ে ওঠা ভেঞ্চার ক্যাপিটাল প্রতিষ্ঠান Startup Bangladesh। সরাসরি স্টার্টআপে বিনিয়োগ, অন্য বিনিয়োগকারীদের সঙ্গে যৌথ বিনিয়োগ, অন্য ফান্ডে অর্থ দেওয়া এবং অর্থের বাইরেও সহায়তা তাদের কাজের মধ্যে আছে। স্টার্টআপের বিনিয়োগ চাওয়া আর ফান্ড ম্যানেজারের নিজের ফান্ডের জন্য অর্থ চাওয়ার আবেদনপদ্ধতি আলাদা।"},"sources":[{"title":"Startup Bangladesh - organization and mandate","url":"https://www.startupbangladesh.vc/about/about-who-we-are/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]},{"id":"application","title":{"en":"Preparing an investment application","bn":"বিনিয়োগের আবেদনের প্রস্তুতি"},"body":{"en":"The startup application asks for founder and team details, business stage, revenue or GMV, company formation, previous investment and a pitch-deck link. Gather these before opening the form. Submitting an application starts a review; it is not an offer of funding.","bn":"আবেদন ফর্মে ফাউন্ডার ও টিমের তথ্য, ব্যবসার স্টেজ, আয় বা GMV, কোম্পানি গঠনের তথ্য, আগের বিনিয়োগ এবং পিচ ডেকের লিংক চাওয়া হয়। ফর্ম খোলার আগে এগুলো গুছিয়ে রাখুন। আবেদন জমা দিলে পর্যালোচনা শুরু হয়, বিনিয়োগের নিশ্চয়তা পাওয়া যায় না।"},"sources":[{"title":"Startup Bangladesh - investment application","url":"https://www.startupbangladesh.vc/contact/apply-for-investment/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[{"label":{"en":"Startup investment application","bn":"স্টার্টআপের বিনিয়োগ আবেদন"},"url":"https://www.startupbangladesh.vc/contact/apply-for-investment/"}]},{"id":"enquiries","title":{"en":"Investment enquiries","bn":"বিনিয়োগ নিয়ে যোগাযোগ"},"body":{"en":"The current contact page lists investment@startupbangladesh.gov.bd for investment enquiries and an office at ICT Tower in Agargaon. Use that page for current contact details: older official FAQ material still displays a different email domain.","bn":"বর্তমান যোগাযোগের পেজে বিনিয়োগসংক্রান্ত প্রশ্নের জন্য investment@startupbangladesh.gov.bd দেওয়া আছে। অফিস আগারগাঁওয়ের আইসিটি টাওয়ারে। যোগাযোগের সর্বশেষ তথ্য এই পেজ থেকেই দেখে নিন। পুরোনো অফিসিয়াল প্রশ্নোত্তরে এখনো ভিন্ন ডোমেইনের ইমেইল দেখা যায়।"},"sources":[{"title":"Startup Bangladesh - current contact information","url":"https://www.startupbangladesh.vc/contact/contact-info/","publishedOn":null,"checkedAt":"2026-09-21"},{"title":"Startup Bangladesh - FAQ with older contact domain","url":"https://www.startupbangladesh.vc/contact/faqs/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[{"label":{"en":"Current contact details","bn":"বর্তমান যোগাযোগের তথ্য"},"url":"https://www.startupbangladesh.vc/contact/contact-info/"}]}],"contact":{"address":{"en":"ICT Tower, Level 14, Plot E-14/X, Agargaon, Dhaka 1207.","bn":"আইসিটি টাওয়ার, লেভেল ১৪, প্লট ই-১৪/এক্স, আগারগাঁও, ঢাকা ১২০৭।"},"email":"investment@startupbangladesh.gov.bd","phone":"+880255006433","sources":[{"title":"Startup Bangladesh - current contact information","url":"https://www.startupbangladesh.vc/contact/contact-info/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('profile-batch1-startup-bangladesh-limited', 'org_startup-bangladesh-limited', 'review', 'editorial:company-profile-batch-1', '2026-09-21', '{"scope":"Official products, services and contact information; previous editorial claims retain their dates."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_priyoshop', '{"sections":[{"id":"products","title":{"en":"Retail sourcing & distribution","bn":"দোকানের পণ্য সংগ্রহ ও বিতরণ"},"body":{"en":"PriyoShop lets retailers order consumer goods from brands through a B2B app and receive deliveries at their shops. Its distribution service connects brands with retail outlets. Shops register with a mobile number, name and shop details before ordering.","bn":"PriyoShop-এর বিটুবি অ্যাপ থেকে দোকানিরা বিভিন্ন ব্র্যান্ডের ভোগ্যপণ্য অর্ডার করে দোকানে ডেলিভারি পান। তাদের বিতরণসেবা ব্র্যান্ডগুলোকে খুচরা দোকানের সঙ্গে যুক্ত করে। অর্ডারের আগে মোবাইল নম্বর, নাম ও দোকানের তথ্য দিয়ে নিবন্ধন করতে হয়।"},"sources":[{"title":"PriyoShop - retail services, founders and offices","url":"https://priyoshop.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[{"label":{"en":"Retail platform","bn":"খুচরা দোকানের প্ল্যাটফর্ম"},"url":"https://priyoshop.com/"}]},{"id":"retail-network","title":{"en":"Services around the retail network","bn":"দোকানের নেটওয়ার্ক ঘিরে সেবা"},"body":{"en":"Alongside sourcing, PriyoShop describes embedded finance for retailers, digital advertising screens inside retail points, and its Dipty house brand of goods such as rice and lentils. These extend the business beyond wholesale ordering into credit access, advertising and own-brand products.","bn":"পণ্য সংগ্রহের পাশাপাশি দোকানিদের অর্থায়ন পাওয়ার সুযোগ, দোকানের ভেতরে ডিজিটাল পর্দায় বিজ্ঞাপন এবং Dipty নামে নিজেদের ব্র্যান্ডের চাল-ডালও আছে PriyoShop-এর সেবায়। ফলে পাইকারি অর্ডারের বাইরেও অর্থায়ন, বিজ্ঞাপন ও নিজস্ব ব্র্যান্ডের পণ্য নিয়ে কাজ করছে তারা।"},"sources":[{"title":"PriyoShop - retail services, founders and offices","url":"https://priyoshop.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"address":{"en":"Bangladesh: 31/A, Dhanmondi 8, Dhaka 1209. Singapore: 160 Robinson Road, #24-09, Singapore 068914.","bn":"বাংলাদেশ: ৩১/এ, ধানমন্ডি ৮, ঢাকা ১২০৯। সিঙ্গাপুর: ১৬০ রবিনসন রোড, #২৪-০৯, সিঙ্গাপুর ০৬৮৯১৪।"},"email":"support@priyoshop.com","phone":"09610989922","sources":[{"title":"PriyoShop - retail services, founders and offices","url":"https://priyoshop.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
